import React, { useState } from 'react';
import { Link, NavLink } from 'react-router-dom';
import { Menu, X, Search, ShoppingCart } from 'lucide-react';

const Navbar = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const handleSearch = (e) => {
    e.preventDefault();
    console.log('Searching for:', searchQuery);
    // Add your search logic here
  };

  return (
    <>
      {/* Top Navigation - Amazon Style */}
      <nav className="bg-amazon-dark text-white fixed w-full top-0 z-50">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex items-center h-16">
            {/* Logo */}
            <Link to="/" className="text-2xl font-bold text-white hover:text-gray-300">
              MyStore
            </Link>

            {/* Search Bar */}
            <form onSubmit={handleSearch} className="flex-1 mx-4">
              <div className="flex">
                <select className="hidden sm:block bg-gray-100 text-gray-700 px-2 rounded-l-lg border-r border-gray-300 text-sm">
                  <option>All</option>
                  <option>Electronics</option>
                  <option>Fashion</option>
                  <option>Home</option>
                </select>
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search products..."
                  className="flex-1 px-4 py-2 text-gray-700 focus:outline-none"
                />
                <button type="submit" className="bg-amazon-orange hover:bg-orange-600 px-6 rounded-r-lg transition-colors">
                  <Search size={20} className="text-gray-800" />
                </button>
              </div>
            </form>

            {/* Right Side */}
            <div className="flex items-center space-x-4">
              <div className="hidden md:block text-sm">
                <span className="text-gray-300">Hello, Sign in</span>
                <div className="font-bold">Account & Lists</div>
              </div>
              <div className="hidden md:block text-sm">
                <span className="text-gray-300">Returns</span>
                <div className="font-bold">& Orders</div>
              </div>
              <button className="relative p-2 hover:text-amazon-orange">
                <ShoppingCart size={28} />
                <span className="absolute -top-1 -right-1 bg-amazon-orange text-gray-800 text-xs font-bold rounded-full h-6 w-6 flex items-center justify-center">
                  0
                </span>
              </button>
            </div>

            {/* Mobile Menu */}
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="md:hidden ml-2 text-white"
            >
              {isOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>

        {/* Mobile Menu Dropdown */}
        {isOpen && (
          <div className="md:hidden bg-amazon-light p-4">
            <div className="space-y-2">
              <Link to="/" className="block text-white hover:text-gray-300">Home</Link>
              <Link to="/about" className="block text-white hover:text-gray-300">About</Link>
              <Link to="/services" className="block text-white hover:text-gray-300">Services</Link>
              <Link to="/contact" className="block text-white hover:text-gray-300">Contact</Link>
            </div>
          </div>
        )}
      </nav>

      {/* Spacer to prevent content from hiding behind fixed navbar */}
      <div className="h-16"></div>
    </>
  );
};

export default Navbar;
